import ast, json

ROOT = "/home/johnson/workspace/LLM_PostProcess"
CORPUS = f"{ROOT}/research/ai-infra-expert/corpus/train.jsonl"
EXP = f"{ROOT}/experiments/2026-08-17-teacher-b-corpus-review"
OUT = f"{EXP}/results/train-batch-0198.jsonl"
START = 1970
N = 10

src = open(f"{EXP}/scripts/tb_gen_batch_0182.py").read()
tree = ast.parse(src)
COMMON_TAIL = None
for node in tree.body:
    if isinstance(node, ast.Assign) and getattr(node.targets[0], "id", "") == "COMMON_TAIL":
        COMMON_TAIL = ast.literal_eval(node.value)
assert COMMON_TAIL and len(COMMON_TAIL) > 2000

rows = [json.loads(l) for l in open(CORPUS) if l.strip()]
sel = rows[START:START + N]
assert len(sel) == N

STANCES = [
    ("Analytical stance under test: kv-cache-dtype-and-quantization-interaction-first - the KV cache is a separate precision axis that must be held fixed.",
     "Falsifiable hypothesis H198a: the KV cache dtype and any KV quantization setting are byte-for-byte identical across arms, verified by dumping the engine's effective KV dtype, per-block byte size and any KV quantization scale configuration from each live serving process. If they differ, the comparison confounds weight precision with KV precision and neither the memory ledger nor the quality delta can be attributed to weight-only quantization.",
     "Weight-only quantization is defined by leaving activations and the KV cache alone, yet many quantization toolchains and serving presets change the KV dtype at the same time, either because a preset bundles them or because a lower KV precision is enabled to exploit the freed memory. That single coupling invalidates the entire study, because KV precision moves both the memory ledger and the quality result through a completely different mechanism than weight precision. Separate the axes explicitly. Dump from each live process the effective KV dtype, the per-block KV byte size, whether KV quantization is enabled and with which scale granularity, and assert equality across arms; then, if KV quantization is genuinely of interest, run it as a third arm rather than folding it into the quantized arm. The mechanisms differ in ways that matter operationally. Weight error is fixed at build time and identical for every request, so its damage is stationary and can be certified once per artefact. KV error accumulates along the sequence and interacts with attention softmax sharpness, so its damage grows with context length and is largest exactly in the long-context regime that memory savings are usually sought to serve. A study that conflates them will observe a quality delta that looks context-dependent and will misattribute it to weights. Boundary condition: where the deployment serves short contexts almost exclusively, KV precision contributes little to either memory or quality and the confound is small, but that must be shown from the served context-length distribution rather than assumed. ESTIMATE: KV pool bytes scale as two times layer count times KV head count times head dimension times total cached tokens times bytes per element, so halving KV element bytes changes the memory ledger by roughly the same order as the weight saving at long context; derivation is byte counting over the KV layout, and it is an ESTIMATE, not MEASURED. Rollback gate: if the runtime dumps disagree on any KV precision property, the run is void and must be re-executed with the axes separated.",
     0.63),

    ("Analytical stance under test: calibration-set-provenance-and-leakage-first - the data used to fit the quantized artefact can contaminate the benchmark that judges it.",
     "Falsifiable hypothesis H198b: no item, near-duplicate or source document from the quantization calibration set appears in the evaluation sets used to certify quality, testable by exact-hash and near-duplicate matching between the calibration corpus and every evaluation slice. If overlap exists, the measured quality parity is inflated by fitting rather than earned, and the certification must be re-run on a disjoint set.",
     "Post-training weight-only quantization methods that use calibration data fit scales, group statistics or error-compensation terms to a sample of text, which makes the quantized artefact a data-dependent object even though no gradient update occurred. That creates a contamination channel most quantization studies never check: if the calibration sample overlaps the evaluation set, the artefact has been tuned toward the exact items used to certify it, and the observed parity partly measures fitting rather than robustness. Audit the boundary mechanically. Record the calibration corpus identity, size, sampling procedure and retention rights in the run manifest; then run exact-hash and near-duplicate matching between calibration items and every evaluation slice, reporting the overlap rate per slice rather than as a single aggregate. Where overlap is non-zero, re-certify on the disjoint remainder and report both numbers. Two secondary effects follow from the same data dependence. Distribution mismatch: a calibration sample drawn from generic web text will under-represent the structured-output, tool-calling and long-context shapes the service actually serves, and weight-only damage concentrates precisely where the calibration distribution is thin, so the artefact can look healthy in aggregate and be materially worse on the slices that carry the SLO. Reproducibility: because the artefact depends on the calibration sample and its ordering, two builds from the same recipe with different samples are different artefacts and their measured deltas are not interchangeable, which means the calibration seed and sample manifest belong in the artefact identity. Boundary condition: calibration-free schemes such as simple round-to-nearest weight quantization do not have this contamination channel, so the check is scheme-dependent and the scheme must be stated. ESTIMATE: the inflation of a slice score is bounded above by the slice's overlap fraction times the difference between fitted and unfitted per-item accuracy, so a small overlap on a small slice can still move a per-slice gate; derivation is decomposing the slice mean into overlapping and disjoint parts, and it is an ESTIMATE, not MEASURED. Rollback gate: no adoption on a certification whose evaluation slices were not shown disjoint from the calibration corpus.",
     0.62),

    ("Analytical stance under test: kernel-dispatch-and-shape-coverage-first - a quantized kernel is fast only on the shapes it has a fast path for.",
     "Falsifiable hypothesis H198c: the quantized kernel's fast path is dispatched for the batch sizes, sequence lengths and tensor shapes actually produced by production traffic, verified by logging the dispatched kernel name and its selection reason per shape across a replayed production trace. If a fallback path is dispatched for a material share of production shapes, the benchmarked speedup does not transfer to the served workload.",
     "Quantized matrix-multiply kernels are not uniformly fast; they are collections of specialised implementations with shape constraints on batch dimension, hidden dimension alignment, group size and sometimes tile-friendly token counts, plus a generic fallback that can be slower than the unquantized baseline. A benchmark run at a single convenient batch size therefore measures one point of a highly non-uniform surface. Map the surface instead. Sweep the shapes that production actually produces, taken from the served batch-size and context-length distributions rather than from round numbers, and log for each shape the dispatched kernel name, whether it is the fast path or a fallback, and the achieved time; then weight the per-shape results by the production frequency of each shape to obtain a traffic-weighted speedup rather than a peak speedup. Two operational consequences follow. Continuous batching produces a wide and time-varying distribution of batch sizes, including many small odd-sized batches at low load and large batches at peak, so a kernel tuned for large aligned batches can leave the common case untouched or regressed, and the aggregate effect depends on the load profile rather than on the kernel's headline number. Autotuning and cache warmth matter: some kernel libraries select implementations by a first-call autotune whose results are cached per shape, so early requests after a restart pay a selection cost and rare shapes may never reach a tuned implementation, which shows up as tail latency rather than as mean regression. Boundary condition: at batch size one the operation is bandwidth-bound and the byte argument is strongest, while at large batch it becomes compute-bound and dequantization overhead can dominate, so the sign of the effect can flip within the served range and a single-number speedup is not well defined. ESTIMATE: the traffic-weighted speedup is the sum over shapes of production share times per-shape measured ratio, which can be far below the best-shape ratio when fallback dispatch covers common shapes; derivation is a frequency-weighted average over the measured shape sweep, and it is an ESTIMATE, not MEASURED. Rollback gate: no adoption without a traffic-weighted shape sweep showing no production-common shape regressed beyond a pre-declared threshold.",
     0.63),

    ("Analytical stance under test: numerical-determinism-and-run-to-run-variance-first - the same arm must reproduce itself before two arms can be compared.",
     "Falsifiable hypothesis H198d: repeated runs of the identical arm with identical inputs and identical seeds produce outputs and metrics within a pre-declared tolerance, testable by executing the same-artefact same-input run several times and measuring the spread of both generated text and timing metrics. If the same arm does not reproduce itself within tolerance, no cross-arm delta smaller than that spread is interpretable.",
     "Before any cross-arm comparison is meaningful, each arm must be shown to reproduce itself, and in a continuous-batching serving engine that is not automatic. Batch composition varies with arrival timing, and many reduction kernels are not deterministic with respect to batch composition, so the same prompt can produce different logits and occasionally different sampled tokens across runs even at fixed seed. Quantized kernels can widen this because their accumulation order and any split-K reduction strategy may be selected dynamically. Establish the self-consistency floor first. Run the same artefact against the same inputs several times under the same scheduler conditions and report the distribution of outputs and of every metric that will later carry the comparison; declare the resulting spread as the noise floor and refuse to interpret any cross-arm delta that does not exceed it. Then decide explicitly whether the study is run in a determinism-forced configuration, with fixed batch composition, disabled non-deterministic reductions and greedy decoding, or in production configuration. Both are legitimate but they answer different questions: the forced configuration isolates numerical differences attributable to precision, while the production configuration measures what users experience including scheduler-induced variance. Do not mix them across arms. Boundary condition: greedy decoding makes token-level divergence a step-function of logit ties, so a tiny numerical perturbation can produce a large text difference at a near-tie without indicating meaningful quality loss, which means text-diff rates overstate damage and should be paired with distributional metrics such as top-1 agreement and logit distance. ESTIMATE: the minimum detectable cross-arm effect is roughly the same-arm spread times a small multiple set by the chosen confidence level and repetition count, so halving the detectable effect requires roughly four times the repetitions; derivation is standard error scaling with the inverse square root of sample count, and it is an ESTIMATE, not MEASURED. Rollback gate: no delta reported without a same-arm reproducibility run establishing the floor under the same scheduler configuration.",
     0.62),

    ("Analytical stance under test: request-cancellation-and-client-disconnect-first - work abandoned mid-stream is charged to capacity but not to any benchmark metric.",
     "Falsifiable hypothesis H198e: the share of production requests cancelled or disconnected before completion is small enough that ignoring them does not change the arm ranking, testable by replaying a trace that includes real cancellation timing on both arms and comparing goodput with and without cancellations. If cancellations are material, benchmark throughput measured on run-to-completion requests overstates both arms and can reorder them.",
     "Streaming serving deployments routinely see clients disconnect mid-generation, whether from user navigation, upstream timeouts or agent loops that stop early once enough tokens have arrived. That work still consumed prefill and decode capacity, still held KV blocks until the engine noticed the cancellation, and still contributed nothing to any completed response, yet almost every quantization benchmark drives run-to-completion requests and therefore never measures it. Include cancellation in the trace. Replay production arrival and cancellation timing, and report goodput, defined as tokens delivered to clients that consumed them, alongside raw throughput; report also the KV block-hours consumed by cancelled requests and the engine's cancellation detection latency, since a slow detection path holds memory that the capacity argument assumed was available. The interaction with quantization is not neutral. If the quantized arm is faster per token, more requests complete before their client gives up, so the cancellation rate itself is arm-dependent and goodput can improve by more than raw throughput; conversely if the quantized arm shifts load toward larger batches with longer queue waits, more requests are abandoned in the queue and goodput can improve by less than throughput, or degrade while throughput improves. Neither direction is knowable without measuring it. Boundary condition: batch and offline inference workloads have no cancellation channel, so this consideration is specific to interactive streaming deployments and should be dropped explicitly rather than silently for offline use cases. ESTIMATE: capacity wasted on abandoned work is approximately the cancelled-request count times the mean tokens generated before cancellation times the per-token decode cost, plus the KV block-hours held until detection; derivation is multiplying observed cancellation statistics by measured per-token cost, and it is an ESTIMATE, not MEASURED. Rollback gate: no throughput-based adoption claim for an interactive service without a goodput number measured under a trace containing real cancellations.",
     0.61),

    ("Analytical stance under test: observability-and-metric-pipeline-integrity-first - the comparison inherits every defect of the instrument that produced its numbers.",
     "Falsifiable hypothesis H198f: the metric pipeline reports the same values for a synthetic workload with known ground truth on both arms, testable by injecting a controlled load with independently known token counts and latencies and comparing pipeline output against ground truth per arm. If the pipeline disagrees with ground truth differently across arms, the reported delta includes measurement error rather than system behaviour.",
     "A quantization verdict is only as trustworthy as the telemetry that produced it, and telemetry is a system with its own failure modes that are rarely audited in benchmark work. Validate the instrument before trusting the reading. Inject a synthetic workload whose token counts and service times are known independently, and confirm that the metric pipeline reproduces them on each arm; then check the specific defects that bias serving comparisons. Histogram bucket boundaries that are coarse near the SLO threshold make percentile estimates quantised and can hide or manufacture a tail difference, so bucket layout must be stated and must be identical across arms. Aggregation across replicas by averaging percentiles is arithmetically invalid and produces a number that tracks neither arm faithfully; percentiles must be computed from merged distributions. Time-to-first-token measured server-side excludes queueing visible only at the load balancer, so an arm that shifts work into the queue can look better server-side and worse to clients. Sampled tracing at low sample rates gives tail estimates with wide uncertainty that is almost never reported alongside the point estimate. Counter resets on restart, and quantized arms often restart more during a study, which silently drops intervals from rate calculations. Clock skew between load generator and server corrupts any latency computed across the boundary. Boundary condition: where the study's decision rule depends on a tail percentile, instrument error concentrates exactly where the decision is made, so tail-driven decisions demand a stricter instrument audit than mean-driven ones. ESTIMATE: percentile quantisation error is bounded by the width of the histogram bucket containing the percentile, so a bucket spanning a wide range around the SLO can obscure a tail difference of comparable size; derivation is worst-case placement within the containing bucket, and it is an ESTIMATE, not MEASURED. Rollback gate: no verdict from a pipeline that has not reproduced a known-ground-truth synthetic load identically on both arms.",
     0.62),

    ("Analytical stance under test: build-and-conversion-cost-amortisation-first - the artefact has a production cost that the savings must repay.",
     "Falsifiable hypothesis H198g: the measured device-hour savings from the quantized arm repay the full conversion, validation and re-certification cost within the artefact's expected service life, testable by measuring conversion compute time, engineer time and validation compute, and dividing by the measured hourly saving. If the payback period exceeds the interval between base-model refreshes, the programme loses money even when every technical claim holds.",
     "Quantization is often justified on steady-state serving cost while its production cost is left out of the ledger, which is an accounting error rather than a technical one. Build the full ledger. On the cost side: conversion or calibration compute time and the device class it required, storage and transfer for the additional artefact, validation compute for the quality and performance certification, engineer time for the study and the rollout, and the recurring repeat of all of the above on every base-model refresh, since a quantized checkpoint is derived from a specific base and does not survive its replacement. On the savings side: the measured device-hour reduction at the actual fleet packing outcome, not the percentage speedup, since savings materialise only when the packing changes. Then compute payback period and compare it against the empirical interval between model refreshes at this organisation. The decisive interaction is that refresh cadence sets the artefact's service life, so a fast-moving model roadmap can make an otherwise sound quantization programme permanently unprofitable, and that is a scheduling fact rather than a numerical one. Two secondary costs belong in the ledger and are usually missed. Operational complexity: two artefact classes in the fleet doubles the certification surface, the rollback matrix and the incident triage space, and that cost is recurring and human. Risk cost: a quality regression discovered in production carries an expected cost equal to its probability times its blast radius, which should be priced rather than assumed zero. Boundary condition: where the fleet is large and the model stable for long periods, amortisation is easy and the technical analysis dominates; where the fleet is small or the model churns, the ledger dominates and the technical result may be irrelevant. ESTIMATE: payback period equals total one-time cost divided by measured hourly saving, and the programme is viable only if that period is shorter than the observed mean interval between base-model refreshes; derivation is simple division over measured inputs, and it is an ESTIMATE, not MEASURED. Rollback gate: no programme approval without a payback period computed from measured conversion and validation cost and compared against the organisation's actual refresh cadence.",
     0.63),

    ("Analytical stance under test: cold-start-and-autoscaling-behaviour-first - the artefact changes how fast capacity can appear, which is a separate SLO.",
     "Falsifiable hypothesis H198h: the time from scale-out decision to a replica serving traffic at steady-state performance is no worse on the quantized arm, testable by measuring artefact pull time, load time, any on-the-fly conversion time, warmup steps to steady state and readiness-probe pass time on both arms from a cold node. If cold start is materially slower, the arm degrades burst response even when its steady-state numbers are better.",
     "Serving cost is driven as much by how quickly capacity can be added as by how efficient a warm replica is, because autoscaled fleets must provision for the peak that arrives before new capacity is ready. Weight-only quantization touches this path in both directions and the net effect must be measured, not assumed. On the favourable side, a smaller artefact pulls from registry or object storage faster and occupies less page cache, which shortens the network-bound portion of cold start. On the unfavourable side, some pipelines perform conversion, repacking or kernel autotuning at load time, which adds a compute-bound phase that the baseline does not have; some quantized loaders are single-threaded where the baseline loader is parallel; and kernel autotune caches are cold on a fresh node, so the first requests run on untuned implementations. Measure the whole path from a genuinely cold node: artefact pull, load and any conversion, CUDA context and graph capture, warmup iterations until step time stabilises, and readiness-probe pass, reporting each phase separately so the regression can be attributed. Then translate into the operational quantity that matters: the headroom the fleet must hold to absorb a burst is proportional to cold-start time times the burst arrival rate, so a slower cold start forces more idle capacity and can cancel the steady-state saving. Boundary condition: fleets that run fixed capacity with no autoscaling are indifferent to this path, so the check should be scoped to elastic deployments and explicitly dropped otherwise. ESTIMATE: required standing headroom scales approximately linearly with cold-start time for a given burst ramp rate, so a doubling of cold start roughly doubles the idle replicas needed to hold the SLO during a ramp; derivation is capacity-deficit integration over the ramp interval, and it is an ESTIMATE, not MEASURED. Rollback gate: no adoption for an elastic fleet without phase-resolved cold-start measurements from a cold node on both arms.",
     0.62),

    ("Analytical stance under test: failure-and-degradation-mode-first - the arms must be compared on how they break, not only on how they perform.",
     "Falsifiable hypothesis H198i: the quantized arm's behaviour under fault injection, covering out-of-memory pressure, device error, network partition to the weight store and abrupt restart, is no worse than the baseline's, testable by running an identical fault-injection suite against both arms and comparing detection time, blast radius and recovery time. If the quantized arm fails differently, the operational risk change must be priced even when steady-state metrics are equal.",
     "Comparisons run on healthy systems say nothing about the property operators care most about, which is how the system behaves when something goes wrong. Run the same fault-injection suite against both arms and compare on operational axes. Memory pressure: drive the engine past its KV headroom and observe whether it degrades gracefully through preemption and admission control or fails hard; a quantized arm configured to a higher memory-utilization fraction to exploit freed bytes has less activation headroom and can convert a survivable burst into an out-of-memory crash. Artefact availability: partition the node from the weight store during a restart and measure whether the replica recovers from local cache or stalls, since a newly introduced artefact may lack the caching and mirroring the baseline enjoys. Device faults: inject an error and compare detection latency and whether the failure is contained to one replica. Abrupt restart: measure in-flight request loss and time to recovered capacity, which couples to the cold-start path. Silent degradation deserves separate treatment because it is the mode most specific to quantization: a numerically damaged arm does not crash, it returns plausible wrong answers, so the detection instrument cannot be liveness probes and must be output-side signals such as parser-failure rate, refusal rate, output-length distribution shift and downstream task-completion rate, each with a pre-declared threshold and an owner. Boundary condition: the higher the memory-utilization setting used to realise the saving, the smaller the safety margin, so the memory-pressure result should be reported as a function of that setting rather than at a single value. ESTIMATE: expected annual incident cost is incident probability times mean blast radius times mean recovery time, so an arm that halves steady-state cost while doubling recovery time may be net negative; derivation is multiplying injected-fault measurements by observed incident base rates, and it is an ESTIMATE, not MEASURED. Rollback gate: no adoption without fault-injection parity and a named output-side silent-degradation alarm in place before traffic shifts.",
     0.63),

    ("Analytical stance under test: decision-authority-and-conflict-of-interest-first - who is allowed to declare the comparison fair determines whether it is.",
     "Falsifiable hypothesis H198j: the comparison's acceptance criteria, slice gates and stopping rule were registered before any measurement, and the party that ran the study is not the sole party authorised to declare it passed, testable by inspecting the pre-registration artefact's timestamp against the first measurement timestamp and the sign-off record. If criteria were set or revised after results were seen, or if the runner is the sole approver, the fairness claim is procedural rather than evidential.",
     "Fairness in a cost-reduction comparison is as much a governance property as a measurement property, because the party proposing the saving usually also designs, runs and interprets the study, and every ambiguous methodological choice then has a direction that favours the proposal. Fix this structurally rather than by asking for care. Pre-register, with a timestamp that precedes the first measurement, the arm definitions, the fixed and varied factors, the primary metric and its SLO percentile, the per-slice quality gates and their tolerances, the noise-floor procedure, the sample size and stopping rule, and the explicit conditions that would constitute a negative result. Store that registration in the same versioned artefact as the results so a reader can diff intent against outcome, and require any deviation to be recorded as an amendment with a reason and a timestamp rather than silently applied. Separate the roles: the team that runs the study proposes, but sign-off requires the service owner who carries the SLO and, for anything touching user-visible quality, an independent reviewer who did not build the artefact. Require the negative case to be pre-specified so that a null result is publishable within the organisation rather than quietly abandoned, since selective reporting across many quantization attempts manufactures apparent wins from noise. Boundary condition: for a low-stakes internal service the full apparatus is disproportionate, and a lighter version, consisting of a written pre-registration and one independent reviewer, retains most of the protection; state which regime applies and why. ESTIMATE: with many uncontrolled analysis choices and selective reporting, the probability that at least one configuration shows a favourable result by chance rises quickly toward certainty, which is why the stopping rule and slice list must be fixed in advance; derivation is multiple-comparison inflation over the number of effectively independent choices, and it is an ESTIMATE, not MEASURED. Rollback gate: no adoption on a study whose acceptance criteria cannot be shown to predate its first measurement.",
     0.64),
]

assert len(STANCES) == N

out = []
for rec, (stance, hyp, body, conf) in zip(sel, STANCES):
    m = {x["role"]: x["content"] for x in rec["messages"]}
    ans = f"{stance}\n\n{hyp}\n\n{body}\n\n{COMMON_TAIL}"
    out.append({
        "source_id": rec["id"],
        "teacher_lane": "teacher-B",
        "teacher_model": "claude-opus-5-current",
        "calibration_status": "provisional",
        "decision": "rewrite",
        "source_user": m["user"],
        "source_assistant": m["assistant"],
        "corrected_answer": ans,
        "quality_dimensions": {
            "technical_correctness": 3,
            "instruction_coverage": 2,
            "operational_safety": 3,
        },
        "risks": [
            "source_assistant restates a grading rubric instead of performing the comparison, so training on it teaches rubric recitation rather than analysis",
            "KV cache dtype is a second precision axis that presets often change alongside weights, confounding weight-only claims with context-length-dependent KV error",
            "calibration data provenance and its overlap with the evaluation set are unchecked, so measured parity can be inflated by fitting rather than earned",
            "quantized kernel fast paths are shape-constrained, so a single-batch-size benchmark can report a speedup that fallback dispatch erases on production shapes",
            "same-arm reproducibility under continuous batching is never established, so cross-arm deltas below the self-consistency floor are treated as real",
            "run-to-completion benchmarking ignores client cancellation, so goodput and the KV block-hours wasted on abandoned work are absent from the ledger",
            "the metric pipeline itself is unaudited, so histogram bucketing, percentile averaging, sampled tracing and clock skew can manufacture or hide a tail delta",
            "conversion, validation and per-refresh re-calibration costs are excluded, so payback period against the organisation's model refresh cadence is never computed",
            "cold-start and autoscaling behaviour are unmeasured, so a slower load or autotune path can force standing headroom that cancels the steady-state saving",
            "failure and silent-degradation behaviour is uncompared, and acceptance criteria are set by the proposing party after seeing results rather than pre-registered",
        ],
        "evidence_required": [
            "runtime dumps of effective KV dtype, per-block KV byte size and KV quantization scale configuration from each live serving process, asserted equal across arms, with KV quantization run as a separate third arm if of interest",
            "calibration corpus identity, size, sampling procedure, seed and retention rights recorded in the manifest, plus exact-hash and near-duplicate overlap rates between calibration items and every evaluation slice, with re-certification on the disjoint remainder",
            "a shape sweep over production-derived batch sizes and context lengths logging dispatched kernel name and fast-path versus fallback selection per shape, reduced to a traffic-weighted speedup rather than a peak speedup",
            "repeated same-artefact same-input runs under the same scheduler configuration reporting the spread of outputs and of every decision metric, with the resulting noise floor declared before any cross-arm delta is interpreted",
            "trace replay including real cancellation and disconnect timing, reporting goodput, cancelled-request KV block-hours and cancellation detection latency alongside raw throughput on both arms",
            "a known-ground-truth synthetic load reproduced identically by the metric pipeline on both arms, with histogram bucket layout, percentile merge method, trace sample rate and clock-skew bound stated",
            "measured conversion compute, storage and transfer, validation compute and engineer time, divided by measured hourly device saving to give a payback period compared against the observed base-model refresh interval",
            "phase-resolved cold-start measurements from a genuinely cold node covering artefact pull, load and conversion, graph capture, warmup to steady state and readiness-probe pass, on both arms",
            "an identical fault-injection suite covering memory pressure at the configured utilization setting, weight-store partition, device error and abrupt restart, reporting detection time, blast radius and recovery time per arm",
            "a timestamped pre-registration of arm definitions, primary metric, per-slice gates, noise-floor procedure, sample size, stopping rule and negative-result conditions predating the first measurement, with amendments logged and sign-off by the SLO owner plus an independent reviewer",
        ],
        "confidence": conf,
    })

with open(OUT, "w") as f:
    for r in out:
        f.write(json.dumps(r, ensure_ascii=False) + "\n")

print("WROTE", OUT, len(out))
print("IDS", ",".join(r["source_id"] for r in out))
print("OPENINGS_DISTINCT", len({r["corrected_answer"][:200] for r in out}))
